package com.mediconnect.controller;
import com.mediconnect.entity.User;import com.mediconnect.enums.UserRole;import com.mediconnect.repository.AvailabilityRepository;import com.mediconnect.repository.UserRepository;import com.mediconnect.service.UserService;import org.springframework.data.domain.Sort;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/doctors") public class DoctorController{
 private final UserRepository users;private final AvailabilityRepository availability;private final UserService service;public DoctorController(UserRepository users,AvailabilityRepository availability,UserService service){this.users=users;this.availability=availability;this.service=service;}
 @GetMapping public List<?> list(@RequestParam(required=false)String q,@RequestParam(required=false)String city){return users.findAll(Sort.by("name")).stream().filter(u->u.getRole()==UserRole.DOCTOR&&u.getVerificationStatus()==com.mediconnect.enums.VerificationStatus.APPROVED&&u.isActive()).map(u->Map.<String,Object>of("id",u.getId().toString(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole().name(),"verificationStatus",u.getVerificationStatus().name())).filter(m->q==null||String.valueOf(m.get("name")).toLowerCase().contains(q.toLowerCase())).toList();}
 @GetMapping("/{id}") public Object get(@PathVariable UUID id){User u=users.findById(id).filter(x->x.getRole()==UserRole.DOCTOR&&x.getVerificationStatus()==com.mediconnect.enums.VerificationStatus.APPROVED&&x.isActive()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));return service.publicUser(u);}
 @GetMapping("/{id}/availability") public List<?> slots(@PathVariable UUID id){if(users.findById(id).filter(u->u.getRole()==UserRole.DOCTOR&&u.getVerificationStatus()==com.mediconnect.enums.VerificationStatus.APPROVED&&u.isActive()).isEmpty())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND);return availability.findByDoctor_IdAndDateGreaterThanEqualAndAvailableTrueOrderByDateAscStartTimeAsc(id,LocalDate.now()).stream().map(a->Map.of("id",a.getId().toString(),"date",a.getDate().toString(),"startTime",a.getStartTime().toString(),"endTime",a.getEndTime().toString())).toList();}
 @PostMapping("/availability") public Object addSlot(@RequestBody SlotRequest body,Authentication auth){User doctor=service.current(auth);if(doctor.getRole()!=UserRole.DOCTOR||doctor.getVerificationStatus()!=com.mediconnect.enums.VerificationStatus.APPROVED)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN);if(body.date()==null||body.date().isBefore(LocalDate.now())||body.startTime()==null||body.endTime()==null||!body.startTime().isBefore(body.endTime()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Choose a future date and valid time slot.");var slot=availability.save(new com.mediconnect.entity.DoctorAvailability(doctor,body.date(),body.startTime(),body.endTime()));return Map.of("id",slot.getId().toString(),"date",slot.getDate().toString(),"startTime",slot.getStartTime().toString(),"endTime",slot.getEndTime().toString());}
 public record SlotRequest(LocalDate date,java.time.LocalTime startTime,java.time.LocalTime endTime){}
}
